<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import type { Comparison, Draft, DraftLine, DraftLineInput, GeneratedLink, Hospital, Manufacturer, OrderSummary, OrderView, PurchaseInput, Session, SupplierTask, MarkupMethod } from '@quote/contracts';
import { ApiFailure, canRetry, checkOperation, mutate, pending, request, retryOperation, session, setSession } from '../../api';
import { recommendation, restoreMarkup, validPositive, type MarkupState } from '../../domain';

const screen=ref<'orders'|'purchase'|'inquiry'|'pricing'>('orders');
const busy=ref(false), error=ref(''), notice=ref(''), conflict=ref(false), foundNotCommitted=ref(false);
const hasChanges=ref(false);
const loginMode=ref<'trial'|'wechat'>('trial'), loginName=ref(''), password=ref(''), bindTicket=ref('');
const hospitals=ref<Hospital[]>([]), manufacturers=ref<Manufacturer[]>([]), orders=ref<OrderSummary[]>([]);
const order=ref<OrderView|null>(null), comparison=ref<Comparison|null>(null), draft=ref<Draft|null>(null);
const hospitalIndex=ref(0), purchaserIndex=ref(0), receivedDate=ref(today()), lines=ref<PurchaseInput[]>([emptyLine()]);
const selectedFactory=ref([0,1]), generated=ref<Record<string,GeneratedLink>>({});
const selectedLineIds=ref<string[]>([]), activeLineId=ref(''), batchScope=ref(0), methodIndex=ref(0), parameter=ref(''), undo=ref<(MarkupState&{purchaseLineId:string})[]|null>(null);
const danger=ref<{mode:'regenerate'|'requote'|'cancel';task:SupplierTask;reason:string}|null>(null);
const methods:MarkupMethod[]=['fixed','percent','multiplier'];const methodLabels=['请选择加价方式','固定金额加价','比例加价（%）','高开倍率加价'];
const hospital=computed(()=>hospitals.value[hospitalIndex.value]);
const purchaser=computed(()=>hospital.value?.purchasers[purchaserIndex.value]);
const isDraftOrder=computed(()=>!order.value||order.value.status==='draft');
const activeLine=computed(()=>draft.value?.lines.find(l=>l.purchaseLineId===activeLineId.value));
const activeComparison=computed(()=>comparison.value?.lines.find(l=>l.purchaseLineId===activeLineId.value));
const pricedLines=computed(()=>draft.value?.lines.filter(l=>l.kind==='priced'&&l.baseValid)||[]);
const batchLines=computed(()=>pricedLines.value.filter(l=>batchScope.value===0||selectedLineIds.value.includes(l.purchaseLineId)));
const changedSupplier=computed(()=>draft.value?.lines.some(l=>l.hasNewSupplierData));
const allMissing=computed(()=>!!draft.value?.lines.length&&draft.value.lines.every(l=>l.kind==='missing'&&l.supplyValid!==false));
const readOnly=computed(()=>!!order.value&&!order.value.writable);
const editingLocked=computed(()=>busy.value||readOnly.value);
const stateLabels:Record<string,string>={quoted:'有效报价',unavailable:'无法供货',pending:'待提交',expired:'报价已过期',requote:'重新报价中',cancelled:'任务已取消'};
function today(){const d=new Date(Date.now()+8*3600000);return d.toISOString().slice(0,10);}
function emptyLine():PurchaseInput{return {name:'',spec:'',quantity:'',checked:false};}
function money(value:string|null|undefined){return value==null?'—':value;}
function stamp(value:string|null){return value?new Date(new Date(value).getTime()+8*3600000).toISOString().replace('T',' ').slice(0,16)+' 北京时间':'未生成';}
function changed(){hasChanges.value=true;notice.value='有未保存修改';}
function ensureWritable(){if(order.value&&!order.value.writable)throw new Error('当前订单为只读，请联系当前负责销售员。');}
function resetWorkspace(){order.value=null;comparison.value=null;draft.value=null;generated.value={};orders.value=[];hospitals.value=[];manufacturers.value=[];screen.value='orders';danger.value=null;notice.value='';error.value='';undo.value=null;selectedLineIds.value=[];activeLineId.value='';methodIndex.value=0;parameter.value='';foundNotCommitted.value=false;hasChanges.value=false;}
function resetOrderContext(){draft.value=null;comparison.value=null;generated.value={};danger.value=null;selectedLineIds.value=[];activeLineId.value='';methodIndex.value=0;parameter.value='';batchScope.value=0;undo.value=null;hasChanges.value=false;notice.value='';selectedFactory.value=[0,1];}
watch(()=>session.value?.user.id,(id,old)=>{if(id!==old)resetWorkspace();},{flush:'sync'});
function pickValue(event:unknown){return Number((event as {detail:{value:string}}).detail.value);}
async function confirm(title:string,content:string){return new Promise<boolean>(resolve=>uni.showModal({title,content,confirmColor:'#216349',success:r=>resolve(r.confirm)}));}
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';conflict.value=false;try{await work();}catch(e){const message=e instanceof Error?e.message:'操作未完成，请重试';if(e instanceof ApiFailure){if(e.status===401||e.code==='UNAUTHORIZED'||e.code==='SESSION_EXPIRED'||e.code==='UNAUTHENTICATED')setSession(null);conflict.value=/VERSION|CONFLICT|STALE/.test(e.code);}error.value=message;}finally{busy.value=false;}}
async function bootstrap(){const [b,o]=await Promise.all([request<{hospitals:Hospital[];manufacturers:Manufacturer[]}>('/sales/bootstrap'),request<{items:OrderSummary[]}>('/sales/purchase-orders')]);hospitals.value=b.hospitals;manufacturers.value=b.manufacturers;orders.value=o.items;}
async function login(){await run(async()=>{const value=await request<Session>(bindTicket.value?'/auth/miniapp/bind-sales':'/auth/trial/password-login','POST',{loginName:loginName.value,password:password.value,...(bindTicket.value?{bindTicket:bindTicket.value}:{})});setSession(value);password.value='';bindTicket.value='';await bootstrap();});}
async function wechatLogin(){await run(async()=>{const code=await new Promise<string>((resolve,reject)=>uni.login({provider:'weixin',success:r=>r.code?resolve(r.code):reject(new Error('未取得微信登录凭证')),fail:()=>reject(new Error('请在微信开发者工具或微信小程序内使用微信登录。'))}));const value=await request<Session|{authState:'identity_unbound';bindTicket:string}>('/auth/miniapp/login','POST',{loginCode:code});if(value.authState==='authenticated'){setSession(value);await bootstrap();}else{bindTicket.value=value.bindTicket;notice.value='微信身份尚未绑定，请填写内部销售账号完成绑定。';}});}
async function logout(){await run(async()=>{await request('/auth/logout','POST',{});setSession(null);order.value=null;draft.value=null;screen.value='orders';});}
async function startPurchase(){if(busy.value)return;if(hasChanges.value&&!await confirm('新建另一张采购单？','当前未保存修改将被放弃。'))return;resetOrderContext();order.value=null;hospitalIndex.value=0;purchaserIndex.value=0;receivedDate.value=today();lines.value=[emptyLine()];notice.value='';screen.value='purchase';}
async function showOrders(){if(busy.value)return;screen.value='orders';await run(bootstrap);}
function viewInquiry(){if(busy.value)return;if(hasChanges.value){error.value='请先保存当前计价修改，再查看询价。';return;}screen.value='inquiry';}
function hydrateOrder(value:OrderView){order.value=value;lines.value=value.lines.map(l=>({id:l.id,name:l.name,spec:l.spec,quantity:l.quantity,checked:l.checked}));receivedDate.value=value.receivedDate;hospitalIndex.value=Math.max(0,hospitals.value.findIndex(h=>h.id===value.hospitalId));purchaserIndex.value=Math.max(0,hospital.value?.purchasers.findIndex(p=>p.id===value.purchaserUserId)||0);hasChanges.value=false;}
async function fetchOrder(){if(order.value)order.value=await request<OrderView>('/sales/purchase-orders/'+order.value.id);}
async function openOrder(id:string){if(busy.value)return;if(hasChanges.value&&!await confirm('打开采购单？','当前未保存修改将被服务器数据替换。'))return;await run(async()=>{const value=await request<OrderView>('/sales/purchase-orders/'+id);if(order.value?.id!==id)resetOrderContext();hydrateOrder(value);screen.value=order.value!.status==='draft'?'purchase':'inquiry';if(screen.value==='inquiry')await loadComparison();});}
async function refresh(){if(busy.value)return;if(hasChanges.value&&!await confirm('重新加载最新数据？','当前未保存修改将被服务器数据替换。'))return;await run(async()=>{if(!order.value||screen.value==='orders'){await bootstrap();return;}const value=await request<OrderView>('/sales/purchase-orders/'+order.value.id);hydrateOrder(value);if(value.status!=='draft'){await loadComparison();if(screen.value==='pricing')await loadDraft();}hasChanges.value=false;notice.value='已重新加载服务器数据';});}
function validatePurchase(){if(!order.value&&(!hospital.value||!purchaser.value))throw new Error('请选择医院及具体采购员。');if(!receivedDate.value)throw new Error('请选择实际接收日期。');if(!lines.value.length||lines.value.some(l=>!l.name.trim()||!validPositive(l.quantity)))throw new Error('每行须填写品名和大于 0、最多两位小数的数量。');}
async function persistPurchase(){ensureWritable();validatePurchase();const input=lines.value.map(l=>({...l.id?{id:l.id}:{},name:l.name,spec:l.spec,quantity:l.quantity,checked:l.checked}));const value=order.value?await mutate<OrderView>('保存采购校对','/sales/purchase-orders/'+order.value.id+'/revisions/'+order.value.revisionId+'/lines','PUT',{expectedVersion:order.value.version,lines:input}):await mutate<OrderView>('新建采购单','/sales/purchase-orders','POST',{hospitalId:hospital.value!.id,purchaserUserId:purchaser.value!.id,receivedDate:receivedDate.value,lines:input});hydrateOrder(value);await fetchOrder();notice.value='采购草稿已保存';}
async function savePurchase(){await run(persistPurchase);}
async function freeze(){if(busy.value)return;if(!await confirm('冻结采购明细？','冻结后本版明细只读，厂家将按此明细报价。'))return;await run(async()=>{if(lines.value.some(l=>!l.checked))throw new Error('请逐行核对并勾选后再冻结。');await persistPurchase();await mutate('冻结采购明细','/sales/purchase-orders/'+order.value!.id+'/revisions/'+order.value!.revisionId+'/freeze','POST',{expectedVersion:order.value!.version});await fetchOrder();screen.value='inquiry';await loadComparison();notice.value='采购明细已冻结';});}
async function loadComparison(){if(order.value)comparison.value=await request<Comparison>('/sales/purchase-orders/'+order.value.id+'/comparison');}
function taskFor(slot:number){return order.value?.tasks.find(t=>t.slotNo===slot&&t.status!=='cancelled');}
async function assign(slot:1|2){await run(async()=>{ensureWritable();const factory=manufacturers.value[selectedFactory.value[slot-1]||0];if(!factory)throw new Error('暂无可选厂家，请联系管理员维护。');await mutate('选择询价厂家','/sales/purchase-order-revisions/'+order.value!.revisionId+'/supplier-tasks','POST',{expectedVersion:order.value!.version,slotNo:slot,manufacturerId:factory.id});await fetchOrder();await loadComparison();});}
async function generate(task:SupplierTask){await run(async()=>{ensureWritable();const result=await mutate<GeneratedLink>('生成厂家链接','/supplier-tasks/'+task.id+'/generate-link','POST',{expectedVersion:order.value!.version});if(result.url)generated.value[task.id]=result;await fetchOrder();notice.value=result.url?'链接已生成，请复制后发送厂家。':'原链接无法恢复，请重新生成。';});}
function copyLink(task:SupplierTask){if(busy.value)return;const url=generated.value[task.id]?.url;if(url)uni.setClipboardData({data:url,success:()=>{notice.value='链接已复制，请自行发送给对应厂家。';}});}
async function commitDanger(){if(busy.value||!danger.value)return;if(hasChanges.value&&draft.value){danger.value=null;error.value='请先返回计价保存当前修改，再重新询价或取消任务。';return;}const action=danger.value;if(!action.reason.trim()){error.value='请填写操作原因';return;}await run(async()=>{ensureWritable();const suffix=action.mode==='regenerate'?'regenerate-link':action.mode;const payload={expectedVersion:order.value!.version,reason:action.reason,...(action.mode==='regenerate'?{expectedLinkId:action.task.linkId}:{}),...(action.mode==='requote'?{expectedSubmissionId:action.task.submissionId}:{})};const result=await mutate<GeneratedLink>('厂家'+suffix,'/supplier-tasks/'+action.task.id+'/'+suffix,'POST',payload);delete generated.value[action.task.id];if(result?.url)generated.value[action.task.id]=result;danger.value=null;await fetchOrder();await loadComparison();if(draft.value)await loadDraft();notice.value=action.mode==='cancel'?'询价任务已取消':'新链接已生成，旧链接及已打开的旧页面已失效。';});}
async function enterPricing(){if(busy.value)return;if(!comparison.value?.submittedCount)return;if(comparison.value.submittedCount===1&&!await confirm('提前进入计价？','另一厂家尚未完整提交。后到报价只更新候选，不自动改写计价草稿。'))return;await run(async()=>{ensureWritable();draft.value=await mutate<Draft>('进入计价','/sales/purchase-orders/'+order.value!.id+'/enter-pricing','POST',{expectedVersion:order.value!.version,allowEarly:comparison.value!.submittedCount===1});await fetchOrder();await loadComparison();screen.value='pricing';activeLineId.value=draft.value.lines[0]?.purchaseLineId||'';notice.value='';});}
async function loadDraft(){draft.value=await request<Draft>('/sales/purchase-orders/'+order.value!.id+'/draft');if(!activeLineId.value||!draft.value.lines.some(l=>l.purchaseLineId===activeLineId.value))activeLineId.value=draft.value.lines[0]?.purchaseLineId||'';undo.value=null;hasChanges.value=false;}
async function refreshCandidates(){await run(async()=>{await fetchOrder();await loadComparison();const latest=await request<Draft>('/sales/purchase-orders/'+order.value!.id+'/draft');draft.value?.lines.forEach(line=>{const updated=latest.lines.find(l=>l.purchaseLineId===line.purchaseLineId);if(updated){line.baseValid=updated.baseSupplierQuoteLineId===line.baseSupplierQuoteLineId?updated.baseValid:line.baseValid;line.supplyValid=updated.supplyValid;line.hasNewSupplierData=updated.hasNewSupplierData;}});notice.value='已刷新报价候选，当前编辑值保留。';});}
async function continuePricing(){if(busy.value)return;if(hasChanges.value&&draft.value?.orderId===order.value?.id){screen.value='pricing';return;}await run(async()=>{await loadDraft();await loadComparison();screen.value='pricing';});}
function toggleLine(id:string){if(busy.value)return;selectedLineIds.value=selectedLineIds.value.includes(id)?selectedLineIds.value.filter(x=>x!==id):[...selectedLineIds.value,id];}
async function applyBatch(){if(busy.value)return;try{ensureWritable();if(!draft.value)return;if(!methodIndex.value)throw new Error('请先选择加价方式。');if(!batchLines.value.length)throw new Error('没有可计价的目标行。');const method=methods[methodIndex.value-1];const updates=batchLines.value.map(l=>({l,value:recommendation(l.basePrice!,method,parameter.value)}));const targetCount=batchScope.value===0?draft.value.lines.length:selectedLineIds.value.length;if(!await confirm('确认批量加价？',methodLabels[methodIndex.value]+'，参数 '+parameter.value+'；影响 '+updates.length+' 行，跳过 '+(targetCount-updates.length)+' 行。仅更新推荐价。'))return;undo.value=updates.map(({l})=>({purchaseLineId:l.purchaseLineId,markupMethod:l.markupMethod,parameterValue:l.parameterValue,recommendedPrice:l.recommendedPrice}));updates.forEach(({l,value})=>{l.markupMethod=method;l.parameterValue=parameter.value;l.recommendedPrice=value;});hasChanges.value=true;notice.value='已更新 '+updates.length+' 行推荐价，请核对后另行采用为最终价。';error.value='';}catch(e){error.value=(e as Error).message;}}
function undoBatch(){if(busy.value)return;if(draft.value&&undo.value){const previous=undo.value;draft.value.lines=draft.value.lines.map(line=>{const old=previous.find(item=>item.purchaseLineId===line.purchaseLineId);return old?restoreMarkup(line,old):line;});undo.value=null;hasChanges.value=true;notice.value='已撤销最近一次批量加价，最终价和基准选择保留。';}}
function chooseBase(event:unknown){if(busy.value)return;const line=activeLine.value;if(!line)return;const cells=activeComparison.value?.cells.filter(c=>c.state==='quoted')||[];const c=cells[pickValue(event)];if(!c)return;line.baseSupplierQuoteLineId=c.supplierQuoteLineId;line.baseManufacturerName=c.manufacturerName;line.basePrice=c.price;line.baseValid=true;line.selectionMode='manual';line.finalConfirmed=false;line.recommendedPrice=line.markupMethod&&line.parameterValue?recommendation(c.price!,line.markupMethod,line.parameterValue):null;changed();}
function applyRecommended(line:DraftLine){if(busy.value)return;if(line.recommendedPrice){line.finalPrice=line.recommendedPrice;line.finalConfirmed=false;changed();}}
function finalChanged(line:DraftLine){line.finalConfirmed=false;changed();}
async function saveDraft(){await run(async()=>{ensureWritable();if(!draft.value)return;const value=draft.value;const inputs:DraftLineInput[]=value.lines.map(l=>({purchaseLineId:l.purchaseLineId,baseSupplierQuoteLineId:l.baseSupplierQuoteLineId,selectionMode:l.selectionMode,markupMethod:l.markupMethod,parameterValue:l.parameterValue,finalPrice:l.finalPrice||null,finalConfirmed:l.finalConfirmed,lossReason:l.lossReason}));draft.value=await mutate<Draft>('保存计价草稿','/quotes/'+value.quoteId+'/versions/'+value.id+'/draft','PUT',{expectedVersion:value.version,hospitalValidUntil:value.hospitalValidUntil,lines:inputs});undo.value=null;hasChanges.value=false;await fetchOrder();notice.value='计价草稿已保存到服务器';});}
async function adopt(){if(busy.value)return;if(!draft.value)return;if(hasChanges.value){error.value='请先保存当前计价修改，再采用最新报价；也可重新加载放弃修改。';return;}if(!await confirm('采用最新厂家报价？','将更新所选行的厂家快照与推荐价，保留已保存最终价；基准变化的行需要重新确认。'))return;await run(async()=>{ensureWritable();const d=draft.value!;draft.value=await mutate<Draft>('采用最新厂家报价','/quotes/'+d.quoteId+'/versions/'+d.id+'/adopt-latest-supplier-quotes','POST',{expectedVersion:d.version,...(selectedLineIds.value.length?{lineIds:selectedLineIds.value}:{})});await fetchOrder();await loadComparison();notice.value='已采用最新报价，请重新核对受影响行。';});}
async function returnAfterCommitted(){resetOrderContext();order.value=null;screen.value='orders';await bootstrap();notice.value='上次操作已成功，请从列表打开对应采购单查看结果。';}
async function checkPending(){await run(async()=>{const status=await checkOperation();foundNotCommitted.value=status==='not_found';if(status==='committed'){await returnAfterCommitted();}else notice.value=canRetry.value?'暂未查到提交结果，请继续核对或按原操作键重试同一次请求。':'暂未查到结果；旧记录缺少原请求内容，请保留待核对并联系维护人员核实。';});}
async function retryPending(){await run(async()=>{await retryOperation();foundNotCommitted.value=false;await returnAfterCommitted();});}
onMounted(()=>{if(session.value)run(async()=>{const user=await request<Session['user']>('/auth/me');if(user.role!=='salesperson')throw new Error('本入口仅供销售员使用');await bootstrap();});});
</script>

<template>
 <view class="app">
  <view class="masthead"><text class="brand">饮片报价</text><text class="account" v-if="session">{{session.user.name}}</text><button class="text-button" v-if="session" @click="logout" :disabled="busy">退出</button></view>
  <view v-if="!session" class="login">
   <text class="eyebrow">销售工作台 · 开发试用</text><text class="title">登录</text>
   <text class="subtle">本批试用：手工采购、厂家询价、比价和计价草稿。数据保存到试用服务器。</text>
   <view class="tabs"><button :class="{active:loginMode==='trial'}" @click="loginMode='trial'" :disabled="busy">开发试用</button><button :class="{active:loginMode==='wechat'}" @click="loginMode='wechat'" :disabled="busy">微信绑定</button></view>
   <view v-if="loginMode==='wechat'&&!bindTicket"><text class="subtle">需配置真实微信 AppID 与服务端密钥；未配置时会提示暂不可用。</text><button class="primary" @click="wechatLogin" :disabled="busy">微信登录 / 绑定销售账号</button></view>
   <view v-if="loginMode==='trial'||bindTicket" class="form">
    <text v-if="bindTicket" class="notice">请绑定已有内部销售账号</text>
    <label class="field"><text>销售账号</text><input v-model="loginName" :disabled="busy" placeholder="请输入销售账号" autocomplete="username" /></label>
    <label class="field"><text>密码</text><input v-model="password" :disabled="busy" password placeholder="请输入密码" autocomplete="current-password" /></label>
    <button class="primary" @click="login" :disabled="busy||!loginName||!password">{{busy?'正在登录…':bindTicket?'绑定并登录':'登录开发试用'}}</button>
    <text class="subtle small">开发试用登录由服务器控制，仅用于非生产环境。</text>
   </view>
  </view>
  <template v-else>
   <view class="navigation"><button class="text-button" @click="showOrders" :disabled="busy">采购单</button><text v-if="order">{{order.orderNo}} · R{{order.revisionNo}}</text><button class="text-button" @click="refresh" :disabled="busy">重新加载</button></view>
   <view v-if="readOnly&&screen!=='orders'" class="notice">当前订单只读；写操作仅限当前负责销售员。</view>
   <view v-if="screen==='orders'" class="workspace">
    <view class="section-head"><text class="title">我的采购单</text><button class="primary compact" @click="startPurchase" :disabled="busy">新建采购单</button></view>
    <text v-if="busy" class="empty">正在读取采购单…</text><text v-else-if="!orders.length" class="empty">暂无采购单，开始录入第一张。</text>
    <button v-for="item in orders" :key="item.id" class="order-row" @click="openOrder(item.id)" :disabled="busy"><view><text class="row-title">{{item.hospitalName}}</text><text class="subtle small">{{item.orderNo}} · {{item.receivedDate}}</text></view><text class="tag">{{item.status==='draft'?'待校对':item.status==='frozen'?'厂家询价':'计价草稿'}} ›</text></button>
   </view>
   <view v-if="screen==='purchase'" class="workspace">
    <text class="eyebrow">手工采购</text><text class="title">采购录入与校对</text>
    <view class="form two">
     <label class="field"><text>医院</text><picker data-testid="hospital-picker" :disabled="busy||!!order" :range="hospitals" range-key="name" :value="hospitalIndex" @change="hospitalIndex=pickValue($event);purchaserIndex=0"><view class="select">{{order?order.hospitalName:hospital?.name||'请选择医院'}}⌄</view></picker></label>
     <label class="field"><text>采购员</text><picker data-testid="purchaser-picker" :disabled="busy||!!order" :range="hospital?.purchasers||[]" range-key="name" :value="purchaserIndex" @change="purchaserIndex=pickValue($event)"><view class="select">{{order?(hospitals.find(h=>h.id===order!.hospitalId)?.purchasers.find(p=>p.id===order!.purchaserUserId)?.name||'原单采购员（已关联）'):purchaser?.name||'请选择采购员'}}⌄</view></picker></label>
    </view>
    <label class="field date-field"><text>实际接收日期</text><picker data-testid="received-date" mode="date" :disabled="busy||!!order" :value="receivedDate" @change="receivedDate=($event as any).detail.value"><view class="select">{{receivedDate}}</view></picker></label>
    <view class="section-head"><text class="section-title">采购明细 · {{lines.length}} 行</text><text class="subtle small">统一 kg</text></view>
    <view v-for="(line,index) in lines" :key="line.id||index" class="purchase-line">
     <view class="section-head"><text class="index">{{String(index+1).padStart(2,'0')}}</text><button class="text-button" :disabled="editingLocked||lines.length===1" @click="lines.splice(index,1);changed()">删除本行</button></view>
     <label class="field"><text>品名</text><input :data-testid="'purchase-name-'+index" :disabled="editingLocked" v-model="line.name" placeholder="填写医院原始品名" @input="line.checked=false;changed()" /></label>
     <view class="two"><label class="field"><text>规格（选填）</text><input :disabled="editingLocked" v-model="line.spec" placeholder="未提供可留空" @input="line.checked=false;changed()" /></label><label class="field"><text>数量 kg</text><input :disabled="editingLocked" v-model="line.quantity" type="digit" placeholder="0.00" @input="line.checked=false;changed()" /></label></view>
     <label class="check-row" :data-testid="'purchase-check-'+index" @click="!busy&&!readOnly&&(line.checked=!line.checked)"><checkbox :disabled="editingLocked" :checked="line.checked" color="#216349" /><text>已核对品名、规格和数量</text></label>
    </view>
    <button class="secondary full" :disabled="editingLocked" @click="lines.push(emptyLine());changed()">＋ 添加采购行</button>
    <view class="action-bar"><button class="secondary" @click="savePurchase" :disabled="busy||readOnly">保存草稿</button><button class="primary" @click="freeze" :disabled="busy||readOnly">校对完成并冻结</button></view>
   </view>
   <view v-if="screen==='inquiry'&&order" class="workspace">
    <text class="eyebrow">{{order.hospitalName}} · {{order.lines.length}} 行</text><text class="title">厂家询价</text>
    <view v-for="slot in [1,2]" :key="slot" class="supplier-section">
     <view class="section-head"><text class="section-title">厂家 {{slot===1?'A':'B'}}</text><text class="tag">{{taskFor(slot)?.status==='submitted'?'已完整提交':taskFor(slot)?.status==='requote'?'重新报价中':taskFor(slot)?'待提交':'待选择'}}</text></view>
     <template v-if="!taskFor(slot)"><picker :data-testid="'manufacturer-picker-'+slot" :disabled="editingLocked" :range="manufacturers" range-key="name" :value="selectedFactory[slot-1]" @change="selectedFactory[slot-1]=pickValue($event)"><view class="select">{{manufacturers[selectedFactory[slot-1]||0]?.name||'请选择厂家'}} ⌄</view></picker><button class="secondary full" @click="assign(slot as 1|2)" :disabled="busy||readOnly">确认询价厂家</button></template>
     <template v-else><text class="row-title">{{taskFor(slot)!.manufacturerName}}</text><text class="subtle small">填写截止：{{stamp(taskFor(slot)!.linkExpiresAt)}}</text><text v-if="taskFor(slot)!.validUntil" class="subtle small">报价有效至 {{taskFor(slot)!.validUntil}}（含当日）</text>
      <view class="button-row" v-if="taskFor(slot)!.status!=='submitted'"><button v-if="!taskFor(slot)!.linkId" class="primary" @click="generate(taskFor(slot)!)" :disabled="busy||readOnly">生成填写链接</button><button v-else-if="generated[taskFor(slot)!.id]?.url" :disabled="editingLocked" class="primary" @click="copyLink(taskFor(slot)!)">复制厂家链接</button><button v-else class="secondary" :disabled="editingLocked" @click="danger={mode:'regenerate',task:taskFor(slot)!,reason:''}">重新生成链接</button><button class="text-button" :disabled="editingLocked" @click="danger={mode:'cancel',task:taskFor(slot)!,reason:''}">取消 / 换厂家</button></view>
      <view class="button-row" v-else><button class="secondary" :disabled="editingLocked" @click="danger={mode:'requote',task:taskFor(slot)!,reason:''}">重新询价并生成新链接</button><button class="text-button" :disabled="editingLocked" @click="danger={mode:'cancel',task:taskFor(slot)!,reason:''}">取消任务</button></view>
      <text v-if="taskFor(slot)!.linkId&&!generated[taskFor(slot)!.id]?.url&&taskFor(slot)!.status!=='submitted'" class="subtle small">原链接只在生成时返回，离开页面后须重新生成。</text>
     </template>
    </view>
    <view class="section-head"><text class="section-title">本次报价对照</text><button class="text-button" @click="run(loadComparison)" :disabled="busy">刷新报价</button></view>
    <view class="compare-table" v-if="comparison"><view class="table-row table-head"><text>药品 / 数量</text><text>A</text><text>B</text><text>最低</text></view><view v-for="row in comparison.lines" :key="row.purchaseLineId" class="table-row"><view><text class="drug">{{row.name}}</text><text class="subtle tiny">{{row.spec||'未提供规格'}}<br/>{{row.quantity}} kg</text></view><view v-for="slot in [1,2]" :key="slot"><template v-if="row.cells.find(c=>c.taskId===taskFor(slot)?.id)"><text>{{money(row.cells.find(c=>c.taskId===taskFor(slot)?.id)?.price)}}</text><text class="tiny subtle">{{stateLabels[row.cells.find(c=>c.taskId===taskFor(slot)?.id)!.state]}}</text></template><text v-else class="subtle tiny">未询价</text></view><text>{{row.kind==='missing'?'缺货':row.kind==='blocked'?'待齐':money(row.lowestPrice)}}</text></view></view>
    <view class="action-bar"><button v-if="order.draftId" class="primary full" @click="continuePricing" :disabled="busy">{{readOnly?'查看计价草稿':'继续计价草稿'}}</button><button v-else class="primary full" @click="enterPricing" :disabled="busy||readOnly||!comparison?.submittedCount">{{comparison?.submittedCount===1?'提前进入计价':'进入计价'}}</button></view>
   </view>
   <view v-if="screen==='pricing'&&draft" class="workspace">
    <view class="section-head"><view><text class="eyebrow">{{order?.hospitalName}}</text><text class="title">计价草稿</text></view><button class="text-button" @click="refreshCandidates" :disabled="busy">刷新报价候选</button><button class="text-button" @click="viewInquiry" :disabled="busy">查看询价</button></view>
    <view v-if="changedSupplier" class="notice"><text>有新的厂家报价，当前草稿保留原快照。</text><button class="text-button" @click="adopt" :disabled="busy||readOnly">采用最新报价{{selectedLineIds.length?'（选中行）':'（全部行）'}}</button></view>
    <view class="batch"><text class="section-title">批量加价</text><view class="two"><picker data-testid="markup-method" :disabled="editingLocked" :range="methodLabels" :value="methodIndex" @change="methodIndex=pickValue($event)"><view class="select">{{methodLabels[methodIndex]}} ⌄</view></picker><input class="input" :disabled="editingLocked" v-model="parameter" type="digit" :placeholder="methodIndex===3?'例如 1.2':'填写加价参数'" /></view><view class="two"><picker data-testid="markup-scope" :disabled="busy" :range="['全部可计价行','选中行']" :value="batchScope" @change="batchScope=pickValue($event)"><view class="select">{{batchScope===0?'全部可计价行':'选中行'}} ⌄</view></picker><text class="subtle">将影响 {{batchLines.length}} 行</text></view><view class="button-row"><button class="secondary" :disabled="editingLocked" @click="applyBatch">更新推荐价</button><button class="text-button" @click="undoBatch" :disabled="busy||!undo||readOnly">撤销最近批量</button></view></view>
    <view class="compare-table"><view class="table-row table-head"><text>选择 / 药品</text><text>基准</text><text>推荐</text><text>最终</text></view><view v-for="line in draft.lines" :key="line.purchaseLineId" class="table-row editable" :class="{current:activeLineId===line.purchaseLineId}" @click="!busy&&(activeLineId=line.purchaseLineId)"><view><view class="select-drug"><checkbox :disabled="busy" :checked="selectedLineIds.includes(line.purchaseLineId)" color="#216349" @click.stop="toggleLine(line.purchaseLineId)"/><text class="drug">{{line.name}}</text></view><text class="tiny subtle">{{line.spec||'未提供规格'}} · {{line.quantity}} kg</text></view><view><text>{{line.kind==='missing'?'缺货':line.kind==='blocked'?'待齐':money(line.basePrice)}}</text><text class="tiny subtle">{{line.baseManufacturerName||''}}</text><text v-if="!line.baseValid&&line.kind==='priced'||line.kind==='missing'&&line.supplyValid===false" class="tiny warning">依据已失效</text></view><text>{{money(line.recommendedPrice)}}</text><view><text>{{line.kind==='missing'?'缺货':money(line.finalPrice)}}</text><text class="tiny subtle">{{line.finalConfirmed?'已确认':'待确认'}}</text></view></view></view>
    <view v-if="activeLine" class="line-editor"><text class="section-title">{{activeLine.name}} · 逐行计价</text><text class="subtle small">{{activeLine.spec||'未提供规格'}} · {{activeLine.quantity}} kg</text>
     <view v-if="activeLine.kind==='priced'">
      <label class="field"><text>基准厂家（只选当前有效报价）</text><picker data-testid="base-manufacturer" :disabled="editingLocked" :range="activeComparison?.cells.filter(c=>c.state==='quoted').map(c=>c.manufacturerName+' · '+c.price+' 元/kg')||[]" @change="chooseBase"><view class="select">{{activeLine.baseManufacturerName||'请选择有效基准'}} · {{money(activeLine.basePrice)}} ⌄</view></picker></label><text class="tiny subtle">{{activeLine.selectionMode==='manual'?'手动锁定基准厂家':'自动采用最低有效价'}} · 当前基准{{activeLine.baseValid?'有效':'已失效'}}</text>
      <view class="recommend"><text>推荐价 {{money(activeLine.recommendedPrice)}} 元/kg</text><button class="text-button" @click="applyRecommended(activeLine)" :disabled="busy||!activeLine.recommendedPrice||readOnly">采用为最终价</button></view>
      <label class="field"><text>最终报价 元/kg</text><input :disabled="editingLocked" v-model="activeLine.finalPrice" type="digit" placeholder="填写或采用推荐价" @input="finalChanged(activeLine)" /></label>
      <label class="field" v-if="activeLine.finalPrice&&activeLine.basePrice&&Number(activeLine.finalPrice)<Number(activeLine.basePrice)"><text class="warning">低于基准价，请填写亏损原因</text><textarea :disabled="editingLocked" v-model="activeLine.lossReason" placeholder="填写本次低价原因" @input="activeLine.finalConfirmed=false;changed()" /></label>
      <label class="check-row"><switch data-testid="final-confirmed" :checked="activeLine.finalConfirmed" color="#216349" @change="activeLine.finalConfirmed=($event as any).detail.value;changed()" :disabled="busy||!activeLine.finalPrice||!activeLine.baseValid||readOnly"/><text>已核对最终价{{activeLine.finalPrice&&activeLine.basePrice&&Number(activeLine.finalPrice)<Number(activeLine.basePrice)?'并确认亏损风险':''}}</text></label>
     </view>
     <text v-else class="subtle">{{activeLine.kind==='missing'?'两家均明确无法供货；保留原行，不参与金额计算。':'厂家报价尚未齐备，当前行暂不能计价。'}}</text>
    </view>
    <label class="field"><text>医院报价有效至（最长 {{draft.maxValidUntil||(allMissing?'不适用':'尚无有效基准')}}）</text><picker mode="date" :value="draft.hospitalValidUntil||''" :end="draft.maxValidUntil||undefined" @change="draft.hospitalValidUntil=($event as any).detail.value;changed()" :disabled="busy||!draft.maxValidUntil||readOnly"><view class="select">{{draft.hospitalValidUntil||(allMissing?'不适用（全部缺货）':'尚无有效基准')}}</view></picker></label>
    <view class="total"><text>服务器已保存总额</text><text>{{draft.total==null?(allMissing?'不适用（全部缺货）':'待完成计价'):'¥ '+draft.total}}</text></view>
    <view class="action-bar"><button class="primary full" @click="saveDraft" :disabled="busy||readOnly">保存计价草稿</button></view>
   </view>
  </template>
  <view v-if="notice" class="notice status">{{notice}}</view><view v-if="error" class="error" role="alert">{{error}}<button class="text-button" v-if="conflict" @click="refresh">重新加载最新数据（放弃本地修改）</button></view>
  <view v-if="pending" class="pending"><text>「{{pending.label}}」结果待核实</text><button class="secondary" @click="checkPending" :disabled="busy">核对操作结果</button><button v-if="foundNotCommitted&&canRetry" class="text-button" :disabled="busy" @click="retryPending">重新提交同一次请求</button><text v-if="foundNotCommitted&&!canRetry" class="subtle small">旧记录缺少原请求内容，请保留待核对并联系维护人员核实。</text></view>
  <view class="overlay" v-if="danger"><view class="dialog"><text class="section-title">{{danger.mode==='requote'?'重新询价并生成新链接':danger.mode==='cancel'?'取消本次厂家任务':'重新生成填写链接'}}</text><text class="subtle">{{danger.mode==='requote'?'旧提交立即退出计算，相关基准及未完成医院报价失效，最终价保留但须重新核对。':danger.mode==='cancel'?'旧链接和本次有效提交立即退出计算；历史记录保留。':'旧链接及已打开的旧填写页面立即失效，新链接从现在起有效 48 小时。'}}</text><label class="field"><text>操作原因</text><textarea :disabled="busy" v-model="danger.reason" placeholder="请填写原因" /></label><view class="button-row"><button class="secondary" @click="danger=null" :disabled="busy">返回</button><button class="primary" @click="commitDanger" :disabled="busy||!danger.reason.trim()">确认操作</button></view></view></view>
 </view>
</template>

