:#fff;flex:1}.secondary{background:#fff;border:1px solid #cdd9ce;color:#216349;flex:1}.text-button{background:transparent;color:#216349;padding:8px 4px;font-size:12px;flex:none}.full{width:100%}.compact{flex:none;font-size:12px;padding:8px 12px}.button-row{display:flex;align-items:center;gap:12px;margin:16px 0 6px}.order-row{display:flex;align-items:center;justify-content:space-between;width:100%;text-align:left;border-bottom:1px solid #e0e7df;background:#fff;padding:20px 0;border-radius:0}.row-title{display:block;font-size:17px;font-weight:550}.tag{font-size:11px;color:#526058;white-space:nowrap}.empty{display:block;padding:40px 0;color:#748077}.purchase-line,.supplier-section{border-bottom:1px solid #e0e7df;padding:15px 0 24px}.index{font-size:11px;color:#748077}.check-row{display:flex;gap:9px;align-items:center;min-height:48px;font-size:12px}.action-bar{display:flex;gap:12px;position:sticky;bottom:0;background:#fffffff5;padding:16px 0 calc(16px + env(safe-area-inset-bottom));margin-top:24px;border-top:1px solid #e0e7df;z-index:2}.compare-table{margin:20px -8px 10px;font-variant-numeric:tabular-nums}.table-row{display:grid;grid-template-columns:minmax(110px,1.7fr) repeat(3,minmax(53px,1fr));gap:8px;padding:14px 8px;border-bottom:1px solid #e0e7df;font-size:12px;align-items:start}.table-row>text:not(:first-child),.table-row>view:not(:first-child){text-align:right}.table-head{background:#f4f7f3;color:#748077;font-size:11px}.drug{font-size:14px;font-weight:550;display:block}.current{background:#edf4ef;border-left:2px solid #216349}.select-drug{display:flex;align-items:center;gap:4px}.select-drug checkbox{transform:scale(.75);transform-origin:left center;width:22px}.batch{padding:20px 0;border-top:1px solid #e0e7df;border-bottom:1px solid #e0e7df}.batch>.two{margin-top:12px}.line-editor{padding:24px 0;border-bottom:1px solid #e0e7df;animation:enter .16s ease-out}.recommend,.total{display:flex;justify-content:space-between;align-items:center;margin:20px 0;font-size:14p